with d as (
  insert into additional_duties (program_key, authority, chapter99_heading, chapter99_heading_at_minimum, label, rate_type,
    rate_pct, origin_countries, hts_scope, condition_text, assume_condition, excludes_programs, exclusion_heading,
    filing_order, effective_from, effective_to, legal_status, source_label, source_url, source_checked_on, notes)
  values ('section_301_china', 'section_301', '9903.88.70', null, 'USTR product exclusion', 'exempt',
    null, array['CN'], 'listed', null, false, '{}', null,
    5, '2024-01-01', '2026-11-09', 'in_force', 'HTS heading 9903.88.70 and U.S. note 20(www) (2026 Rev. 20); extended through November 9, 2026 (FR 2025-21671)', 'https://hts.usitc.gov/reststop/file?release=2026HTSRev20&filename=Chapter%2099', '2026-10-03', 'Exclusions depend on the product description, not only the HTS code, so they are never applied automatically. Each line carries the exclusion''s text.')
  returning id
)
